(function(){
'use strict';
const G=SignalGame,root=document.getElementById('app'),dlg=document.getElementById('hintDialog');
const KEY='signal-station-session-v2',RK='signal-station-teacher-v2',DK='signal-station-drafts-v2',ROOMS_KEY='signal-station-managed-rooms-v1';
const levelNames=['Dễ','Trung bình','Khá','Ác mộng','Địa ngục'],levelPoints=[100,200,350,550,800];
const names=['Lời khai','Thẻ truy cập','Nguồn điện','Bộ mã','Kênh cứu hộ'];
let state=null,screen='landing',pendingName='',pendingRoom='',feedback='',lastDigit=null,reports=[],hintTap=0,toastTimer,session=read(KEY,null),teacherSession=read(RK,null),board=null,busy=false,clockOffset=0,peers=[],managedRooms=read(ROOMS_KEY,[]),sessionNotice='',managementPending=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=ms=>{let n=Math.max(0,Math.floor(ms/1000));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Trình duyệt không lưu được tiến độ. Giữ trang này mở khi chơi.');return false;}}
function save(){if(state)write(DK,{id:state.id,round:state.round||1,drafts:state.drafts||{}});}
function toast(text){let el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function header(){return `<header class="top"><div class="brand"><span class="brand-mark" aria-hidden="true">◈</span> TRẠM MẤT TÍN HIỆU</div><div class="top-actions"><button class="ghost" data-action="rules">Luật & hướng dẫn</button>${state?'<button class="ghost" data-action="shop">Kỹ năng</button>':''}<a href="?view=teacher">Giáo viên</a></div></header>`;}
async function start(){try{busy=true;let d=await api('join',{name:pendingName,code:pendingRoom});session=d.session;sessionNotice='';write(KEY,session);apply(d);screen=state.status==='waiting'?'waiting':state.status==='active'?'play':'result';render();}catch(e){toast(e.message);}finally{busy=false;}}
function landing(){return `${header()}<main class="landing"><div>${sessionNotice?`<p class="notice session-notice" role="status">${esc(sessionNotice)}</p>`:''}<div class="eyebrow">Hồ sơ cứu hộ · Trạm 07</div><h1>TRẠM MẤT<br><span>TÍN HIỆU</span></h1><p>Một cơn bão. Năm hệ thống bị khóa.<br>Đội của bạn là hy vọng cuối cùng để đưa trạm nghiên cứu trở lại mạng lưới cứu hộ.</p><div class="chips"><span>TOÁN 10 & SUY LUẬN LOGIC</span><span>3–4 NGƯỜI / NHÓM</span><span>30 PHÚT</span></div>${state&&state.status==='active'?`<p class="small">Đang có phiên của <strong>${esc(state.name)}</strong>. Đồng hồ vẫn chạy khi rời trang sau khi giáo viên bắt đầu.</p><button class="primary" data-action="resume">Tiếp tục nhiệm vụ</button>`:state?`<p class="small">Phiên gần nhất: <strong>${esc(state.name)}</strong>.</p><div class="flex"><button class="primary" data-action="result">Xem kết quả</button><button data-action="new">Tạo phiên mới</button></div>`:`<form id="joinForm" class="join" style="flex-wrap:wrap"><label for="teamName" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden">Tên nhóm</label><input id="roomCode" name="roomCode" placeholder="Mã phòng từ giáo viên" maxlength="6" required autocomplete="off" aria-label="Mã phòng"><input id="teamName" name="teamName" placeholder="Tên nhóm, ví dụ: 10 Olinda – Nhóm 2" maxlength="40" required autocomplete="off"><button class="primary">Nhận nhiệm vụ</button></form>`}<p><button data-action="rules">Đọc đầy đủ luật chơi</button></p><footer>Nhập mã phòng giáo viên cung cấp. Mỗi nhóm dùng chung một thiết bị; gợi ý và lượt gửi sai được ghi nhận tự động trên máy chủ.</footer></div></main>`;}
function briefing(){return `${header()}<main class="setup"><div class="eyebrow">Đội ${esc(pendingName)}</div><h1>30 phút để khôi phục trạm.</h1><p class="muted">Sét đánh đã ngắt máy phát, khóa kho thẻ và làm hỏng bộ mã. Cửa thoát chỉ mở khi máy phát truyền được tín hiệu cứu hộ. Đọc các hồ sơ còn lại, kiểm tra dữ kiện và phục hồi từng hệ thống theo thứ tự.</p><div class="roles"><div class="role"><strong>Người đọc hồ sơ</strong><span class="muted">Đọc dữ kiện, nhắc điều kiện.</span></div><div class="role"><strong>Người suy luận</strong><span class="muted">Đề xuất cách giải, tính toán.</span></div><div class="role"><strong>Người kiểm tra</strong><span class="muted">Tìm phản ví dụ, kiểm tra kết quả.</span></div><div class="role"><strong>Người điều khiển</strong><span class="muted">Nhập câu trả lời đã thống nhất.</span></div></div><p class="small muted">Nhóm 3 người có thể gộp hai vai. Đổi vai sau mỗi khóa. Chuẩn bị giấy nháp và bút.</p>${rulesBody()}<button class="primary" data-action="start">Vào phòng · Chờ giáo viên bắt đầu</button></main>`;}
function field(key,label,placeholder='',text=false){let val=state.drafts[state.solved.length]?.[key]??'';return `<div class="field"><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" value="${esc(val)}" placeholder="${esc(placeholder)}" ${text?'':'inputmode="numeric" pattern="[0-9]+"'} autocomplete="off" required maxlength="40"></div>`;}
function content(i,v){if(state.puzzles?.[i]){let p=state.puzzles[i];return {title:p.title,narrative:levelNames[p.level]+' · '+p.points+' điểm · Hệ thống '+names[i].toLowerCase(),evidence:p.question.map(q=>`<p>${esc(q)}</p>`).join('')+lab(p),instruction:'Dùng bảng thử để kiểm chứng, rồi nhập toàn bộ kết quả nhóm đã thống nhất.',fields:p.fields.map(f=>field(f.key,esc(f.label),'',f.text)).join('')+(p.widget.kind==='power'?`<input type="hidden" id="pipe-answer" name="circuit" value="${pipeTurns.join(',')}">`:'')};}switch(i){case 0:return {title:'Ai giữ chìa khóa thật?',narrative:'Muốn vào phòng điều khiển, đội cần xác định tủ chứa chìa khóa. Ba bản ghi an ninh còn nguyên, nhưng chỉ một bản ghi nói đúng.',evidence:`<h2>Biên bản an ninh</h2><p>Chìa khóa nằm trong đúng một tủ A, B hoặc C. Có <strong>đúng một</strong> lời khai đúng.</p><div class="quote"><b>A</b> “Chìa khóa nằm ở tủ B.”</div><div class="quote"><b>B</b> “Chìa khóa không nằm ở tủ B.”</div><div class="quote"><b>C</b> “Chìa khóa không nằm ở tủ A.”</div><p style="margin-top:22px">Phiếu gắn trên chìa khóa ghi:</p><div class="math">n ∈ {2; 4; 6; 8}, &nbsp; 12 không chia hết cho n.</div><p class="small muted">n là chữ số thứ nhất của mã cửa. Không được suy ra “mọi lời khai còn lại đều đáng tin” sau khi tìm thấy một lời đúng.</p>`,instruction:'Lập ba trường hợp cho vị trí chìa khóa. Nhập số lời khai đúng ở từng trường hợp, vị trí hợp lệ và số n.',fields:`<div class="rowfields">${field('countA','Nếu chìa ở A')}${field('countB','Nếu chìa ở B')}${field('countC','Nếu chìa ở C')}</div>${field('cabinet','Tủ thực sự chứa chìa khóa','Nhập chữ cái',true)}${field('digit','Số n trên phiếu')}`};
case 1:return {title:'Lọc thẻ truy cập.',narrative:'Phòng máy dùng hai bộ lọc thẻ khác nhau. Phải đối chiếu danh sách, đếm đúng số thẻ và tìm nhóm thẻ dự phòng để khôi phục quyền truy cập.',evidence:`<h2>Nhật ký hai bộ lọc</h2><div class="math">U = {1; 2; …; ${v.N}}<br>A = {n ∈ U | n là số chẵn}<br>B = {n ∈ U | n chia hết cho 3}</div><p>Thẻ qua cả hai bộ lọc thuộc <span class="math">A ∩ B</span>. Thẻ qua ít nhất một bộ lọc thuộc <span class="math">A ∪ B</span>.</p><p>Thẻ dự phòng là thẻ thuộc A nhưng không thuộc B. <strong>Số thẻ dự phòng</strong> là chữ số thứ hai của mã cửa.</p>`,instruction:'Liệt kê thẻ chung; đếm số thẻ qua ít nhất một bộ lọc và số thẻ dự phòng. Chú ý không đếm lặp thẻ chung.',fields:field('intersection','Các phần tử của A ∩ B','Ngăn cách bằng dấu phẩy hoặc dấu chấm phẩy',true)+field('union','Số phần tử của A ∪ B')+field('difference','Số phần tử của A ∖ B')};
case 2:return {title:'Cấp điện mà không quá tải.',narrative:'Các thẻ đã mở kho pin. Một pin cho đèn và hai pin cho mỗi bộ máy phát. Đội cần chọn phương án cho nhiều máy phát nhất mà vẫn đủ đèn.',evidence:`<h2>Phiếu phân phối điện</h2><p>Gọi x là số bộ máy phát, y là số bộ đèn. Cả x và y là <strong>số nguyên dương</strong>.</p><div class="math">x + y = ${v.T}<br>2x + y ≤ ${v.T+v.c}<br>x ≥ 1, &nbsp; y ≥ 1</div><p>Mỗi bộ máy phát dùng 2 pin; mỗi bộ đèn dùng 1 pin. Chọn phương án có <strong>x lớn nhất</strong>.</p><p>x là chữ số thứ ba. Để chứng minh tối ưu, tính số pin cần dùng nếu tăng x thêm 1 nhưng vẫn giữ tổng x + y bằng ${v.T}.</p>`,instruction:'Không chỉ tìm một cặp thỏa điều kiện: hãy chứng minh không thể tăng thêm máy phát.',fields:`<div class="rowfields" style="grid-template-columns:1fr 1fr">${field('x','Số máy phát x')}${field('y','Số bộ đèn y')}</div>${field('power','Số pin dùng: 2x + y')}${field('rejected','Số pin nếu tăng x thêm 1, giữ nguyên tổng số bộ')}`};
case 3:{let a=['●','◆','▲','■','✚'].slice(0,v.cycles[0]),b=['Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ'].slice(0,v.cycles[1]);return {title:'Đồng bộ hai nhịp mã.',narrative:'Máy phát đã hoạt động nhưng hai dãy tín hiệu lệch nhịp. Bảng điều khiển chỉ mở khi cả hai dãy trở lại đúng cặp ký hiệu đầu tiên.',evidence:`<h2>Băng ghi tín hiệu</h2><p>Mỗi dãy lặp lại theo một chu kỳ cố định. Hai dãy chuyển ký hiệu <strong>cùng lúc, một lần mỗi giây</strong>.</p><div class="seq-label">DÃY A · KÝ HIỆU</div><div class="sequence">${[...a,...a].map(x=>`<span class="signal">${x}</span>`).join('')}<span class="muted">…</span></div><div class="seq-label">DÃY B · MÃ ROMAN</div><div class="sequence">${[...b,...b].map(x=>`<span class="signal">${x}</span>`).join('')}<span class="muted">…</span></div><p>Lúc <strong>t = 0</strong>, màn hình hiển thị cặp ký hiệu đầu tiên. Tìm số giây nhỏ nhất <strong>t &gt; 0</strong> để cả hai dãy cùng trở lại cặp này.</p><p>Chữ số thứ tư là <strong>tổng các chữ số của t</strong>.</p>`,instruction:'Xác định chu kỳ nhỏ nhất của mỗi dãy, rồi tìm thời điểm đồng bộ đầu tiên. Không nhầm “một dãy lặp lại” với “cả hai dãy lặp lại”.',fields:`<div class="rowfields" style="grid-template-columns:1fr 1fr">${field('periodA','Chu kỳ dãy A (giây)')}${field('periodB','Chu kỳ dãy B (giây)')}</div>${field('joint','Thời điểm t nhỏ nhất (giây)')}${field('sum','Tổng các chữ số của t')}`};}
case 4:return {title:'Tìm kênh cứu hộ.',narrative:'Máy phát đã đồng bộ. Dải tần cứu hộ bị nhiễu, còn đèn báo chưa chuyển xanh. Cần chọn đúng kênh và đọc đúng ý nghĩa của đèn báo trước khi phát tín hiệu.',evidence:`<h2>Nhật ký tần số & đèn báo</h2><p>Kênh n là số nguyên thỏa:</p><div class="math">${v.channel.n-4} &lt; n &lt; ${v.channel.n+2}<br>n là số lẻ<br>n không chia hết cho ${v.channel.d}</div><p>Quy định của trạm: <strong>“Nếu đèn xanh thì đã kết nối.”</strong> Gọi P = 1 khi đèn xanh, Q = 1 khi đã kết nối; giá trị 0 biểu thị điều ngược lại.</p><p>Đèn hiện không xanh (P = 0). Hãy nêu giá trị Q cho thấy <strong>đèn không xanh chưa đủ để kết luận mất kết nối</strong>.</p><p>Chữ số cuối của mã cửa là <strong>chữ số hàng đơn vị của n</strong>.</p>`,instruction:'Nhập kênh phù hợp, số lẻ ngay trước nó bị loại bởi điều kiện chia hết, và giá trị Q chứng minh cách suy luận về đèn.',fields:field('channel','Kênh n')+field('excluded','Số lẻ ngay trước n bị loại')+field('connected','Giá trị Q của phản ví dụ')};}}


function levelChoice(){let i=state.solved.length;return `${header()}<main class="setup"><div class="statusbar"><strong>${esc(state.name)}</strong>${clocks()}</div>${stationMap(i)}<div class="eyebrow">Khóa ${i+1}/5 · ${names[i]}</div><h1>Đội chọn thử thách nào?</h1><p>Khôi phục hệ thống ${names[i].toLowerCase()}. Cùng mục tiêu, mỗi mức có hồ sơ và ràng buộc khác nhau. Độ khó được giữ cố định sau khi nhận đề; đồng hồ vẫn chạy.</p><div class="level-grid">${levelNames.map((n,l)=>`<button data-action="choose-level" data-level="${l}"><strong>${n}</strong><span>${levelPoints[l]} điểm</span><span>${['Dữ kiện trực tiếp','Kết hợp hai bước','Thêm điều kiện kiểm tra','Dữ kiện gián tiếp, nhiều ràng buộc','Đối chiếu đồng thời, dễ mắc bẫy suy luận'][l]}</span></button>`).join('')}</div><p>Tổng điểm hiện tại: <strong>${state.score||0}</strong>. Xếp hạng ưu tiên số khóa hoàn tất, rồi điểm, rồi thời gian cộng phạt.</p>${inventory()}</main>`;}
function lab(p){let w=p.widget;if(!w)return '';let body='';if(w.kind==='truth')body='<p>Chạm từng ô để ghi Đúng (Đ), Sai (S) hoặc chưa xét (?). Đây là bảng lập luận của đội; hệ thống không tự chọn đáp án.</p><div class="tablewrap"><table><thead><tr><th>Chìa ở</th><th>Bản ghi 1</th><th>Bản ghi 2</th><th>Bản ghi 3</th></tr></thead><tbody>'+['A','B','C'].map(x=>`<tr><th>${x}</th>${[1,2,3].map(j=>`<td><button type="button" data-action="lab-truth" aria-label="Chìa ở ${x}, bản ghi ${j}">?</button></td>`).join('')}</tr>`).join('')+'</tbody></table></div>';if(w.kind==='sets')body='<p>Chạm các thẻ để đánh dấu phần tử nhóm muốn kiểm tra. Bảng này không tự phân loại hay chấm đáp án.</p><div class="tokens">'+Array.from({length:w.N},(_,i)=>`<button type="button" data-action="lab-token" aria-pressed="false">${i+1}</button>`).join('')+'</div>';if(w.kind==='power')body=`<label>Thử số máy phát x <input id="lab-x" type="range" min="1" max="${w.T-1}" value="1"></label><meter id="power-meter" min="0" max="${w.budget}" value="${w.k+w.T-1}"></meter><output id="lab-output">Kéo thanh để thử cách phân phối. Tự đối chiếu tất cả điều kiện trên hồ sơ.</output>`;if(w.kind==='clock')body='<label>Thử thời điểm t (giây) <input id="lab-t" type="range" min="0" max="150" value="0"></label><output id="lab-output">Kéo thanh để quan sát vị trí hai dãy.</output><div id="rhythm-a" class="rhythm-strip"></div><div id="rhythm-b" class="rhythm-strip"></div>';if(w.kind==='logic')body='<p>Đánh dấu tình huống để thảo luận: điều kiện của trạm có cấm tình huống này không? Việc đánh dấu không tính là gửi đáp án.</p><div class="tokens">'+['Đèn xanh · Đã kết nối','Đèn xanh · Chưa kết nối','Đèn không xanh · Đã kết nối','Đèn không xanh · Chưa kết nối'].map(t=>`<button type="button" data-action="lab-token" aria-pressed="false">${t}</button>`).join('')+'</div>';return `<section class="lab"><h2>Bàn thử của đội</h2>${body}${w.kind==='power'?pipeUI():''}</section>`;}
function updateLab(){let w=state?.puzzles?.[state.solved.length]?.widget,out=document.getElementById('lab-output');if(!w||!out)return;if(w.kind==='power'){let x=Number(document.getElementById('lab-x').value),y=w.T-x;let meter=document.getElementById('power-meter');if(meter)meter.value=w.k*x+y;out.textContent=`x = ${x}; y = ${y}; số pin = ${w.k*x+y}. Đối chiếu giới hạn pin và các điều kiện còn lại.`;}if(w.kind==='clock'){let t=Number(document.getElementById('lab-t').value);for(let [id,n,r] of [['rhythm-a',w.a,w.ra],['rhythm-b',w.b,w.rb]]){let el=document.getElementById(id);if(el)el.innerHTML=Array.from({length:n},(_,j)=>`<span class="${j===((t-r)%n+n)%n?'lit':''}">${j+1}</span>`).join('');}out.textContent=`t = ${t} giây · Dãy A ở vị trí ${((t-w.ra)%w.a+w.a)%w.a+1}/${w.a} · Dãy B ở vị trí ${((t-w.rb)%w.b+w.b)%w.b+1}/${w.b}. Cả hai phải ở vị trí 1.`;}}


function rulesBody(){return `<section class="rules full-rules"><h2>Quy ước của đội cứu hộ</h2><p><strong>Nhiệm vụ:</strong> đi qua 5 khu vực để khôi phục an ninh, thẻ truy cập, nguồn điện, bộ mã và kênh cứu hộ. Mỗi khóa cho một chữ số. Ghép đúng thứ tự để mở cửa cuối trong 30 phút.</p><ol><li><strong>Chia vai:</strong> nhóm 3–4 người, chung một thiết bị; người đọc, người suy luận, người kiểm tra, người điều khiển. Đổi vai sau mỗi khóa. Được dùng giấy nháp.</li><li><strong>Chọn độ khó:</strong> Dễ 100; Trung bình 200; Khá 350; Ác mộng 550; Địa ngục 800 điểm. Chọn trước mỗi khóa, không đổi sau khi nhận đề. Điểm chỉ được nhận khi giải đúng cả bộ dữ kiện.</li><li><strong>Bàn thử:</strong> dùng thẻ, bảng lời khai, thanh phân phối pin, mô phỏng đồng hồ và đường ống để kiểm chứng. Thao tác thử không bị phạt; chỉ nút “Xác nhận” gửi đáp án.</li><li><strong>Gợi ý:</strong> mở lần lượt 3 mức, cộng 1 / 2 / 3 phút vào thời gian xếp hạng. Dùng cả 3 cộng 6 phút. Đọc lại miễn phí. Mỗi mức mới đóng băng nút gửi trong 8 / 12 / 16 giây để đội đọc và thảo luận; vẫn được xem đề và bàn thử.</li><li><strong>Gửi sai:</strong> cộng 1 phút, chờ 10 giây rồi gửi lại. Không chỉ ra ô nào sai. Nhóm phải kiểm tra toàn bộ kết quả.</li><li><strong>Điểm và kỹ năng:</strong> điểm đã kiếm được có thể tiêu. Phá băng 20 điểm xóa đóng băng hiện tại; Lá chắn 40 điểm chặn gây nhiễu trong 60 giây; Tiếp sức 30 điểm phá băng và bảo vệ nhóm khác 20 giây; Nhiễu tín hiệu 60 điểm đóng băng nhóm khác 20 giây. Phá băng không xóa phút phạt đã ghi.</li><li><strong>Giới hạn chiến thuật:</strong> mở ít nhất 1 khóa mới được mua kỹ năng. Chỉ tác động nhóm đang chơi và đã mở ít nhất 1 khóa khi gây nhiễu. Mỗi đội tối đa 2 lần gây nhiễu, cách nhau 60 giây; mỗi đội chỉ nhận tối đa 2 lần. Sau khi bị gây nhiễu được bảo vệ 60 giây. Không tác động nhóm đã chốt kết quả. Mua thất bại không trừ điểm.</li><li><strong>Xếp hạng:</strong> ưu tiên số khóa hoàn tất, rồi điểm còn lại; nếu bằng nhau, ưu tiên thời gian thực chơi cộng phạt nhỏ hơn. Điểm tiêu cho kỹ năng làm giảm điểm xếp hạng. Kết quả chốt khi mở cửa hoặc hết 30 phút.</li><li><strong>Đồng hồ:</strong> dùng giờ chung của phòng, không dừng khi đóng băng, mất mạng hoặc tải lại. Thời gian phạt được cộng khi xếp hạng, không trừ khỏi 30 phút chơi. Đội vào muộn dùng thời gian còn lại.</li><li><strong>Kết nối:</strong> dùng lại thiết bị đã vào phòng. Khi chưa có xác nhận máy chủ, giữ câu trả lời và chờ kết nối. Giáo viên theo dõi tiến độ, lời giải, các lượt gửi và kỹ năng tự động.</li></ol><p>Trong lúc chơi, luôn có thể mở <strong>Luật & hướng dẫn</strong>, <strong>Gợi ý</strong> hoặc <strong>Kỹ năng</strong> ở đầu trang. Bản đồ cho biết khu vực hiện tại và các chặng đã khôi phục.</p></section>`;}
function rulesDialog(){dlg.dataset.kind='rules';dlg.innerHTML='<button class="close" data-action="close-hints">Đóng</button>'+rulesBody();if(!dlg.open)dlg.showModal();}
function stationMap(i){return `<nav class="mission-map" aria-label="Bản đồ trạm nghiên cứu"><div class="map-caption">LỘ TRÌNH CỨU HỘ · ${i>=5?'Đã đến cửa thoát':'Bạn đang ở khu '+(i+1)}</div><div class="map-route">${names.map((n,j)=>`<div class="map-stop ${j<i?'restored':j===i?'here':'locked'}" ${j===i?'aria-current="step"':''}><span>${j<i?'✓':String(j+1).padStart(2,'0')}</span><strong>${n}</strong><small>${j<i?'Đã khôi phục':j===i?'Đang có mặt':'Chưa tới'}</small></div>`).join('')}<div class="map-stop exit ${i===5?'here':''}"><span>◈</span><strong>Cửa thoát</strong><small>${i===5?'Nhập mã':'Cuối hành trình'}</small></div></div></nav>`;}
const skillNames={thaw:'Phá băng',shield:'Lá chắn',help:'Tiếp sức',freeze:'Nhiễu tín hiệu'},skillCosts={thaw:20,shield:40,help:30,freeze:60};
async function shopDialog(){if(!session||!state)return;try{let r=await fetch('/api/escape?kind=crew&id='+encodeURIComponent(session.id),{headers:{Authorization:'Bearer '+session.token},cache:'no-store'});let d=await r.json();if(!r.ok)throw Error(d.error);peers=d.peers;}catch(e){toast(e.message);return;}dlg.dataset.kind='shop';dlg.innerHTML=`<button class="close" data-action="close-hints">Đóng</button><div class="eyebrow">Kho tiếp tế · Chiến thuật của đội</div><h2><span id="shop-wallet">${state.score||0}</span> điểm có thể tiêu</h2><p>Kiếm được ${state.effects?.earned??state.score??0} · Đã tiêu ${state.effects?.spent||0}. Mở ít nhất một khóa mới được mua. Điểm đã tiêu làm giảm điểm xếp hạng.</p><label>Nhóm khác nhận tác động<select id="skillTarget">${peers.filter(p=>p.id!==state.id&&p.status==='active').map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.completed}/5 khóa</option>`).join('')}</select></label><div class="skill-grid">${Object.entries(skillNames).map(([k,n])=>`<section><h3>${n} · ${skillCosts[k]} điểm</h3><p>${{thaw:'Xóa đóng băng hiện tại; giữ nguyên thời gian phạt.',shield:'Chặn gây nhiễu trong 60 giây.',help:'Phá băng và bảo vệ nhóm khác 20 giây.',freeze:'Đóng băng nhóm khác 20 giây. Tối đa 2 lần; mỗi lần cách nhau 60 giây.'}[k]}</p><button class="primary" data-action="buy-skill" data-skill="${k}" ${state.status!=='active'||state.solved.length<1||state.score<skillCosts[k]?'disabled':''}>Dùng ${n}</button></section>`).join('')}</div>${personalSkills()}`;if(!dlg.open)dlg.showModal();}
async function buySkill(skill){if(busy)return;busy=true;try{let target=document.getElementById('skillTarget')?.value,d=await api('skill',{id:session.id,skill,target});apply(d);toast(d.skill?'Đã dùng '+d.skill.name+' · Trừ '+d.skill.cost+' điểm':'Đã ghi nhận kỹ năng');await shopDialog();updateClock();}catch(e){toast(e.message);}finally{busy=false;}}
function personalSkills(){return `<details id="personal-skills"><summary>Nhật ký kỹ năng (${state.effects?.history?.length||0})</summary>${(state.effects?.history||[]).map(a=>`<p>${time(a.created-state.start)} · ${a.actor_id===state.id?'Đội dùng':'Đội nhận'} ${skillNames[a.kind]}${a.actor_id===state.id?' · −'+a.cost+' điểm':''}</p>`).join('')}</details>`;}
function teacherSkills(r){return `<details id="skills-${esc(r.id)}"><summary>Kỹ năng đã dùng và đã nhận (${r.effects?.history?.length||0})</summary>${(board.skills||[]).filter(a=>a.actor_id===r.id||a.target_id===r.id).map(a=>`<p>${time(a.created-Date.parse(r.start))} · ${esc(a.actor)} dùng ${skillNames[a.kind]} cho ${esc(a.target)} · ${a.cost} điểm</p>`).join('')}</details>`;}
let pipeTurns=[0,0,0,0,0,0,0,0,0];const pipeBase=[[1,2],[0,2],[0,3],[0,1],[1,3],[2,3],[1,2],[0,2],[0,3]];
function pipeUI(){return `<div class="pipe-workbench"><p>Khôi phục đường ống: xoay từng khớp để nối lối vào bên trái ô 1 đến lối ra bên phải ô 9. Cần nối thông đường ống và tính đúng phương án pin để mở khóa.</p><div class="pipe-grid">${pipeBase.map((_,i)=>`<button type="button" data-action="lab-pipe" data-cell="${i}" aria-label="Xoay khớp ${i+1}"><svg viewBox="0 0 80 80" aria-hidden="true"><g id="pipe-${i}">${pipeLines(i)}</g></svg></button>`).join('')}</div><button type="button" data-action="check-pipe">Thử dòng tín hiệu</button><output id="pipe-feedback">Lối vào: cạnh trái ô 1. Lối ra: cạnh phải ô 9.</output></div>`;}
function pipeLines(i){let ends=pipeBase[i].map(x=>(x+pipeTurns[i])%4),pts=[[40,0],[80,40],[40,80],[0,40]];return ends.map(x=>`<path d="M40 40 L${pts[x][0]} ${pts[x][1]}" fill="none" stroke="currentColor" stroke-width="13" stroke-linecap="round"/>`).join('');}
function rotatePipe(i){pipeTurns[i]=(pipeTurns[i]+1)%4;document.getElementById('pipe-'+i).innerHTML=pipeLines(i);let input=document.getElementById('pipe-answer');if(input){input.value=pipeTurns.join(',');input.dispatchEvent(new Event('input',{bubbles:true}));}}
function checkPipe(){let dirs=pipeBase.map((x,i)=>x.map(d=>(d+pipeTurns[i])%4)),seen=new Set(),queue=dirs[0].includes(3)?[0]:[];while(queue.length){let i=queue.shift();if(seen.has(i))continue;seen.add(i);for(let d of dirs[i]){let r=Math.floor(i/3),c=i%3,n=d===0?i-3:d===1?i+1:d===2?i+3:i-1;if(d===0&&r===0||d===2&&r===2||d===1&&c===2||d===3&&c===0)continue;if(dirs[n].includes((d+2)%4))queue.push(n);}}let ok=seen.has(8)&&dirs[8].includes(1);document.getElementById('pipe-feedback').textContent=ok?'Dòng tín hiệu đã nối thông. Đối chiếu dữ kiện nguồn điện để mở khóa.':'Dòng tín hiệu đang ngắt. Kiểm tra các cạnh nối đối diện.';}

function clocks(){return `<div class="effect-status" id="effectStatus" role="status"></div><div class="clocks"><div class="clock"><small>THỜI GIAN CÒN LẠI</small><span id="remaining">${time(G.DURATION-(now()-state.start))}</span></div><div class="clock penalty"><small>PHẠT TỰ ĐỘNG</small><span id="penalty">+${time(state.penalty)}</span></div></div>`;}
function inventory(){return `<div class="inventory"><div><strong>Nhật ký mã cửa</strong><div class="muted small">Các chữ số đã khôi phục, theo thứ tự khóa.</div></div><div class="codes">${Array.from({length:5},(_,i)=>`<span class="code ${i>=state.solved.length?'empty':''}">${state.solved[i]??'·'}</span>`).join('')}</div></div>`;}
function gameplay(){if(state.levels&&state.solved.length<5&&state.levels[state.solved.length]===null)return levelChoice();let i=state.solved.length,v=state.variant;if(i>=5)return finalGate();if(state.puzzles?.[i]?.widget.kind==='power'){let saved=state.drafts[i]?.circuit;if(saved){let turns=saved.split(',').map(Number);if(turns.length===9&&turns.every(n=>Number.isInteger(n)&&n>=0&&n<=3))pipeTurns=turns;}}let c=content(i,v);return `${header()}<main class="shell"><div class="statusbar"><div><div class="eyebrow">Đội cứu hộ</div><div class="team">${esc(state.name)}</div></div>${clocks()}</div>${stationMap(i)}<div class="gamecols"><section class="clue"><div class="eyebrow">Khóa ${i+1} / 5 · ${names[i]}</div><h1>${c.title}</h1><p class="narrative">${c.narrative}</p><div class="evidence">${c.evidence}</div><p class="instruction">${c.instruction}</p></section><aside class="answer"><h2>Đối chiếu hồ sơ</h2><p class="muted small">Thống nhất cả bộ kết quả trước khi gửi. Gửi sai: +1 phút.</p><form id="answerForm">${c.fields}<button class="primary" id="submitAnswer">Xác nhận · Mở khóa</button></form><div class="feedback" id="feedback" role="status" aria-live="polite">${esc(feedback)}</div><div class="hintline"><button data-action="hints">Gợi ý · ${state.hints[i].length}/3</button><span>Mở lần lượt.<br>Phạt +1 / +2 / +3 phút.</span></div><p class="small muted" style="margin-top:20px;margin-bottom:0">Tiến độ tự lưu trên máy chủ. Đồng hồ vẫn chạy khi rời trang sau khi giáo viên bắt đầu.</p></aside></div>${inventory()}</main>`;}
function success(){let i=state.solved.length-1;return `${header()}<main class="success"><div class="eyebrow">Khóa ${i+1} đã khôi phục</div><h1>${['Đã tìm được chìa khóa.','Quyền truy cập đã mở.','Nguồn điện đã ổn định.','Hai nhịp mã đã đồng bộ.','Tín hiệu cứu hộ sẵn sàng.'][i]}</h1><div class="digit">${lastDigit??state.solved[i]}</div><p class="score-earned">Điểm còn lại: <strong>${state.score||0}</strong></p><p>Chữ số thứ ${['nhất','hai','ba','tư','năm'][i]} đã được ghi vào nhật ký. Đổi vai trong nhóm trước khi tiếp tục.</p><button class="primary" data-action="continue">${i===4?'Đến cửa thoát':'Mở hồ sơ tiếp theo'}</button><p class="small muted" style="margin-top:25px">Đồng hồ vẫn chạy. Phạt hiện tại: +${time(state.penalty)}.</p>${inventory()}</main>`;}
function finalGate(){return `${header()}<main class="shell"><div class="statusbar"><div class="team">${esc(state.name)}</div>${clocks()}</div>${stationMap(5)}<div class="finalcols"><section><div class="pipe-unlock" aria-hidden="true">◈ ◈ ◈ ◈ ◈</div><div class="eyebrow">Cửa thoát · Kiểm tra cuối</div><h1>Trạm đã phát được tín hiệu.</h1><p class="muted">Ghép năm chữ số theo đúng thứ tự trong nhật ký. Nhập mã để mở cửa an toàn và chốt thời gian của đội.</p>${inventory()}</section><section class="answer"><h2>Mã cửa an toàn</h2><form id="finalForm"><div class="field"><label for="finalCode">Năm chữ số, từ khóa 1 đến khóa 5</label><input id="finalCode" name="code" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" autocomplete="off" required placeholder="Nhập mã 5 chữ số"></div><button class="primary" id="submitAnswer">Mở cửa · Chốt kết quả</button></form><div id="feedback" class="feedback" role="status">${esc(feedback)}</div><p class="small muted">Gửi sai vẫn cộng 1 phút và khóa lượt gửi 10 giây.</p></section></div></main>`;}
function recordResult(){/* The server is authoritative; result is already persisted. */}
function result(){let r=G.report(state,now()),h=r.hints.reduce((a,b)=>a+b,0);return `${header()}<main class="result"><div class="eyebrow">Hồ sơ nhiệm vụ · ${esc(r.team)}</div><h1>${r.status==='completed'?'Đã mở cửa an toàn.':'Hết thời gian cứu hộ.'}</h1><p class="muted">${r.status==='completed'?'Đội đã khôi phục đủ năm hệ thống và truyền tín hiệu cứu hộ.':'Đội đã khôi phục '+r.completed+'/5 hệ thống. Kết quả và lịch sử gợi ý đã được chốt.'}</p><div class="metrics"><div class="metric">Thời gian thực chơi<strong>${time(r.elapsedMs)}</strong></div><div class="metric">Tổng thời gian phạt<strong>+${time(r.penaltyMs)}</strong></div><div class="metric">Thời gian xếp hạng<strong>${time(r.adjustedMs)}</strong></div></div><p><strong>${state.score||0} điểm còn lại</strong> · Kiếm được ${state.effects?.earned??state.score??0}, đã tiêu ${state.effects?.spent||0}<p><strong>${state.score||0} điểm</strong> · <strong>${h} mức gợi ý</strong> đã mở · <strong>${r.wrong} lượt gửi sai</strong> · <strong>${r.completed}/5 khóa</strong>.</p><div class="log tablewrap"><table><thead><tr><th>Khóa</th><th>Mức gợi ý đã dùng</th><th>Phạt do gợi ý</th></tr></thead><tbody>${names.map((n,i)=>`<tr><td>${i+1}. ${n}</td><td>${r.hints[i]===0?'Không dùng':Array.from({length:r.hints[i]},(_,j)=>j+1).join(', ')}</td><td>+${time(G.HINT_COST.slice(0,r.hints[i]).reduce((a,b)=>a+b,0))}</td></tr>`).join('')}<tr><td colspan="2">${r.wrong} lượt gửi sai × 1 phút</td><td>+${time(r.wrong*G.WRONG_COST)}</td></tr></tbody></table></div><div class="flex"><button class="primary" data-action="download">Tải báo cáo nhóm (.json)</button><button data-action="print">In / Lưu PDF</button><button class="ghost" data-action="new">Tạo phiên mới</button></div><p class="small muted" style="margin-top:25px">Kết quả đã được ghi nhận tự động trên bảng giáo viên. Tệp báo cáo là bản sao để lưu lại; không cần gửi tệp để tính phạt hoặc xếp hạng.</p>${personalSkills()}<details><summary>Nhật ký tự động</summary><div class="tablewrap"><table><thead><tr><th>Thời điểm</th><th>Sự kiện</th><th>Phạt</th></tr></thead><tbody>${r.events.map(e=>`<tr><td>${time(e.at-state.start)}</td><td>${e.type==='hint'?`Khóa ${e.lock} · Mở mức gợi ý ${e.level}`:e.type==='wrong'?`Gửi sai · ${e.lock===6?'Cửa thoát':'Khóa '+e.lock}`:e.type==='solved'?`Đã mở khóa ${e.lock}`:e.type==='timeout'?'Hết 30 phút':e.type==='level'?'Khóa '+e.lock+' · Chọn '+levelNames[e.level]:'Đã mở cửa thoát'}</td><td>${e.cost?'+'+time(e.cost):'—'}</td></tr>`).join('')}</tbody></table></div></details></main>`;}
function hintDialog(){dlg.dataset.kind='hint';let i=state.solved.length;if(i>=5||state.status!=='active')return;let opened=state.hints[i].length,hs=state.hintTexts[i];dlg.innerHTML=`<button class="close ghost" data-action="close-hints" aria-label="Đóng gợi ý">×</button><div class="eyebrow">Hỗ trợ giàn giáo · Khóa ${i+1}</div><h2 id="hintTitle">Gợi ý: ${names[i].toLowerCase()}</h2><p class="muted small">Mỗi lần mở thêm một mức, hệ thống tự ghi nhận và cộng phạt. Các mức đã mở có thể đọc lại miễn phí.</p>${hs.map((h,j)=>`<section class="hint-card"><b>MỨC ${j+1} · ĐÃ TÍNH +${j+1} PHÚT</b><p>${h}</p></section>`).join('')}${opened<3?`<section class="hint-card"><p class="muted">${['Mức 1 nhắc kiến thức cần dùng.','Mức 2 chỉ đường và bước giải đầu tiên.','Mức 3 giúp gần hoàn tất lời giải.'][opened]}</p><button class="primary" data-action="buy-hint">Mở mức ${opened+1} · Tự cộng ${opened+1} phút</button></section>`:'<p class="muted">Đã mở đủ ba mức ở khóa này. Hãy đối chiếu các ô cần nhập.</p>'}<p class="cost">Phạt do gợi ý ở khóa này: +${time(G.HINT_COST.slice(0,opened).reduce((a,b)=>a+b,0))} · Tổng phạt của đội: +${time(state.penalty)}</p>`;if(!dlg.open)dlg.showModal();}
function sorted(){return reports.slice().sort((a,b)=>{if(a.completed!==b.completed)return b.completed-a.completed;if((a.score||0)!==(b.score||0))return (b.score||0)-(a.score||0);let status={completed:0,active:1,timeout:2,waiting:3};return status[a.status]-status[b.status]||(a.status!=='completed'?b.completed-a.completed:0)||a.adjustedMs-b.adjustedMs;});}

const inputLabels={circuit:'Hướng các khớp ống',countA:'Lời đúng nếu ở A',countB:'Lời đúng nếu ở B',countC:'Lời đúng nếu ở C',cabinet:'Tủ',digit:'Chữ số',intersection:'Giao A ∩ B',union:'Số phần tử hợp',difference:'Số phần tử hiệu',x:'Máy phát x',y:'Đèn y',power:'Số pin',rejected:'Pin nếu tăng x',periodA:'Chu kỳ A',periodB:'Chu kỳ B',joint:'Thời điểm đồng bộ',sum:'Tổng chữ số',channel:'Kênh n',excluded:'Số bị loại',connected:'Q',code:'Mã cửa'};
function inputsText(v){return Object.entries(v||{}).map(([k,x])=>`${esc(inputLabels[k]||k)}: <strong>${esc(x||'—')}</strong>`).join(' · ')||'Chưa nhập câu trả lời.';}
function teamDetail(r){let active=Math.min(r.completed,5),finished=['completed','timeout'].includes(r.status),rank=sorted().filter(x=>['completed','timeout'].includes(x.status)).findIndex(x=>x.id===r.id)+1;return `<details class="team-detail" id="team-${esc(r.id)}"><summary><strong>${esc(r.team)}</strong> · ${finished?'Kết quả chi tiết':r.status==='waiting'?'Đang chờ':r.levels&&r.levels[active]===null?'Đang chọn mức độ cho khóa '+(active+1):active===5?'Đang nhập mã cửa':'Đang làm khóa '+(active+1)+' · '+names[active]}${finished?' · Hạng '+rank:''}</summary><div class="detail-body"><p>${r.status==='completed'?'Đã thoát':r.status==='timeout'?'Hết giờ':r.status==='waiting'?'Chờ giáo viên bắt đầu':'Đang chơi'} · ${r.completed}/5 khóa · ${r.score||0} điểm · Thực chơi ${time(r.elapsedMs)} · Phạt +${time(r.penaltyMs)} · Xếp hạng ${time(r.adjustedMs)}</p>${!finished&&r.status==='active'?`<section class="notice"><strong>Nội dung nhóm đang làm: ${active===5?'Cửa thoát':r.guide[active].title}</strong>${active===5?'<p>Ghép năm chữ số từ khóa 1 đến khóa 5 để mở cửa.</p>':r.guide[active].question.map(q=>`<p>${esc(q)}</p>`).join('')}<p>Bản nháp đang nhập: ${inputsText(r.drafts[active])}</p></section>`:''}<p>Điểm kiếm được: ${r.effects?.earned??r.score??0} · Đã tiêu: ${r.effects?.spent||0} · Còn lại: ${r.score||0}. ${r.effects?.freezeUntil>now()?'Đang đóng băng đến '+time(r.effects.freezeUntil-Date.parse(r.start)):''}</p><h2>Đề, đáp án và lời giải theo phiên của nhóm</h2>${r.guide.map((g,i)=>{let ev=r.events.filter(e=>e.lock===i+1),solved=ev.find(e=>e.type==='solved'),wrong=ev.filter(e=>e.type==='wrong').length,hintCost=G.HINT_COST.slice(0,r.hints[i]).reduce((a,b)=>a+b,0),start=i===0?Date.parse(r.start):r.events.find(e=>e.type==='solved'&&e.lock===i)?.at;return `<details id="guide-${esc(r.id)}-${i}" class="guide-lock"><summary>Khóa ${i+1}: ${esc(g.title)} · ${solved?'Đã mở':finished?'Chưa mở':'Chưa hoàn tất'}</summary><div class="detail-body">${g.question.map(q=>`<p>${esc(q)}</p>`).join('')}<p>${r.levels&&r.levels[i]!==null?levelNames[r.levels[i]]+' · '+levelPoints[r.levels[i]]+' điểm':'Phiên gốc'}</p><p class="solution-answer"><strong>Đáp án:</strong> ${esc(g.answer)} · Chữ số ${g.digit}</p><ol>${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>Hint: ${r.hints[i]}/3 · Gửi sai: ${wrong} · Phạt khóa: +${time(hintCost+wrong*60000)}${solved&&start?' · Thời gian giải: '+time(solved.at-start):''}</p><p>Câu trả lời gần nhất: ${inputsText(r.drafts[i])}</p></div></details>`;}).join('')}${teacherSkills(r)}<p><strong>Mã cửa đúng:</strong> ${r.guide.map(g=>g.digit).join('')}</p><details id="attempts-${esc(r.id)}"><summary>Lịch sử câu trả lời đã gửi (${r.submissions.length})</summary><div class="tablewrap"><table><thead><tr><th>Thời điểm</th><th>Khóa</th><th>Câu trả lời</th><th>Kết quả</th></tr></thead><tbody>${r.submissions.map(a=>`<tr><td>${time(a.at-Date.parse(r.start))}</td><td>${a.lock===6?'Cửa thoát':a.lock}</td><td>${inputsText(a.input)}</td><td>${a.ok?'Đúng':'Sai · +1 phút'}</td></tr>`).join('')}</tbody></table>${r.submissions.length?'':'<p>Các lượt gửi trước bản cập nhật này chưa lưu nội dung; lịch sử hint và phạt vẫn được giữ.</p>'}</div></details></div></details>`;}

function teacher(){let ready=reports.length;return `${header()}<main class="teacher"><div class="eyebrow">Điều phối đội cứu hộ · Toán 10</div><h1>Phòng cứu hộ của lớp.</h1>${roomPicker()}<p class="muted">Tiến độ, hint và thời gian phạt được ghi trên máy chủ. Bảng tự cập nhật mỗi 3 giây.</p>${!teacherSession?`<form id="roomForm" class="upload"><label for="roomTitle">Tên buổi chơi</label><input id="roomTitle" name="roomTitle" value="Escape Toán 10" maxlength="60" required><button class="primary">Tạo phòng chơi</button></form>`:`<section class="rules"><h2>${esc(board?.room.title||teacherSession.title||'Phòng cứu hộ')}</h2><div class="eyebrow">MÃ PHÒNG HỌC SINH · LƯỢT ${board?.room.round||1}</div><div class="flex"><strong style="font-size:42px;letter-spacing:.12em;color:var(--gold)">${esc(board?.room.code||teacherSession.code)}</strong><span>${ready} nhóm đã vào</span><button class="primary" data-action="begin-room" ${board?.room.started||!ready?'disabled':''}>${board?.room.started?'Nhiệm vụ đang chạy':'Bắt đầu đồng hồ cho cả lớp'}</button></div><p class="small muted" style="margin:20px 0 0">Cung cấp mã phòng và trang học sinh. Chờ các đội vào đủ rồi bắt đầu. Nhóm vào muộn dùng thời gian còn lại của lớp.</p></section><div class="flex"><button data-action="csv" ${ready?'':'disabled'}>Tải bảng xếp hạng CSV</button><button data-action="create-another-room">Tạo phòng khác</button><button data-action="reset-room" ${!board?'disabled':''}>Reset phòng · Chơi lại</button><button class="danger" data-action="delete-room" ${!board?'disabled':''}>Xóa phòng</button><a href="?" target="_blank" rel="noopener">Mở trang học sinh</a></div><p id="boardStatus" class="small muted" role="status">Đang tự cập nhật từ máy chủ.</p><section class="tablewrap"><table><thead><tr><th>Hạng</th><th>Nhóm</th><th>Trạng thái</th><th>Khóa</th><th>Thực chơi</th><th>Phạt</th><th>Xếp hạng</th><th>Hint / khóa</th><th>Sai</th><th>Quản lý</th></tr></thead><tbody>${sorted().map((r,i)=>`<tr><td>${['completed','timeout'].includes(r.status)?sorted().filter(x=>['completed','timeout'].includes(x.status)).findIndex(x=>x.id===r.id)+1:'—'}</td><td>${esc(r.team)}<br><strong>${r.score||0} điểm</strong></td><td>${r.status==='completed'?'Đã thoát':r.status==='waiting'?'Chờ bắt đầu':r.status==='timeout'?'Hết giờ':'Đang chơi'}</td><td>${r.completed}/5</td><td>${time(r.elapsedMs)}</td><td>+${time(r.penaltyMs)}</td><td>${r.status==='waiting'?'—':time(r.adjustedMs)}</td><td>${r.hints.join(' / ')}</td><td>${r.wrong}</td><td><button class="danger" data-action="remove-team" data-team="${esc(r.id)}" aria-label="Xóa đội ${esc(r.team)}">Xóa đội</button></td></tr>`).join('')}</tbody></table>${ready?'':'<div class="empty-state">Chưa có đội nào vào. Cung cấp mã phòng cho các nhóm.</div>'}</section><section class="team-dossiers"><h2>Hồ sơ từng nhóm</h2><p class="muted">Mở tên nhóm để xem đề đang làm, bản nháp, đáp án và lời giải. Tự cập nhật mỗi 3 giây. Giữ màn hình này riêng cho giáo viên khi học sinh đang chơi.</p>${sorted().map(teamDetail).join('')}</section>`}<section class="notice"><strong>Cách tổ chức:</strong> nhóm 3–4 học sinh dùng chung một thiết bị. Game yêu cầu nhập cả kết quả và dữ kiện trung gian; giáo viên yêu cầu nhóm trình bày cách giải khóa khó nhất khi tổng kết. Khuyến nghị 3 phút phân vai, 30 phút chơi, 7 phút tổng kết.</section><details><summary>Quy tắc phạt và xếp hạng</summary><p>Mỗi mức gợi ý được tính đúng một lần: mức 1 +1 phút, mức 2 +2 phút, mức 3 +3 phút. Gửi sai +1 phút và chờ 10 giây. Xếp hạng theo số khóa hoàn tất, rồi tổng điểm giảm dần, rồi thời gian thực chơi cộng phạt tăng dần. Nhóm chưa hoàn tất hiển thị số khóa đã mở. Thời gian phạt không trừ thời gian thực còn lại.</p></details><p class="small muted">Quyền quản lý phòng được lưu trên trình duyệt giáo viên đã tạo phòng. Học sinh chỉ cần mã phòng. Không cung cấp quyền quản lý hoặc dùng chung thiết bị giáo viên với học sinh.</p></main>`;}
function render(){let opened=[...root.querySelectorAll('details[open][id]')].map(e=>e.id);if(screen==='teacher')root.innerHTML=teacher();else if(screen==='briefing')root.innerHTML=briefing();else if(screen==='waiting')root.innerHTML=waiting();else if(screen==='play')root.innerHTML=gameplay();else if(screen==='success')root.innerHTML=success();else if(screen==='result')root.innerHTML=result();else root.innerHTML=landing();updateLab();opened.forEach(id=>{let el=document.getElementById(id);if(el)el.open=true;});updateClock();}
function updateClock(){if(!state||state.status!=='active')return;let currentTime=now();let wallet=document.getElementById('shop-wallet');if(wallet)wallet.textContent=state.score||0;let frozen=Math.max(0,Math.ceil(((state.effects?.freezeUntil||0)-currentTime)/1000));let ef=document.getElementById('effectStatus');if(ef)ef.textContent=frozen?'ĐÓNG BĂNG '+frozen+' giây · '+state.effects.freezeSource:(state.effects?.shieldUntil>currentTime?'Lá chắn đang bảo vệ nhóm':'Nhóm sẵn sàng');let el=document.getElementById('remaining');if(el){el.textContent=time(G.DURATION-(currentTime-state.start));el.classList.toggle('low',G.DURATION-(currentTime-state.start)<300000);}let p=document.getElementById('penalty');if(p)p.textContent='+'+time(state.penalty);let btn=document.getElementById('submitAnswer');if(btn){let left=Math.ceil((state.cooldown-currentTime)/1000);btn.disabled=busy||frozen>0||left>0||currentTime-state.start>=G.DURATION;btn.textContent=frozen>0?'Đóng băng '+frozen+' giây · Có thể đọc hồ sơ':left>0?'Đợi '+left+' giây · Kiểm tra lại':state.solved.length===5?'Mở cửa · Chốt kết quả':'Xác nhận · Mở khóa';}}
function download(filename,obj){let blob=new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:typeof obj==='string'?'text/csv;charset=utf-8':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function handleReply(r){if(r.ok){feedback='';lastDigit=r.digit;if(state.status==='completed'){screen='result';recordResult();}else screen='success';save();render();window.scrollTo({top:0,behavior:'instant'});}else if(r.reason==='wrong'){feedback='Dữ kiện chưa khớp. Đã cộng 1 phút. Cả nhóm kiểm tra lại hồ sơ trước khi gửi.';save();let el=document.getElementById('feedback');if(el)el.textContent=feedback;toast('Gửi sai · Tự cộng 1 phút');updateClock();}else if(r.reason==='frozen'){toast('Nhóm đang đóng băng. Có thể đọc hồ sơ, chờ hết giờ hoặc dùng Phá băng.');updateClock();}else if(r.reason==='inactive'){screen=state.status==='active'?'play':'result';save();render();}else toast('Chờ hết 10 giây rồi gửi lại.');}
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;if(e.target.id==='joinForm'){let fd=new FormData(e.target);pendingName=fd.get('teamName').trim();pendingRoom=fd.get('roomCode').trim().toUpperCase();if(!pendingName||!pendingRoom){toast('Nhập mã phòng và tên nhóm.');return;}screen='briefing';render();window.scrollTo(0,0);}else if(e.target.id==='roomForm'){let title=new FormData(e.target).get('roomTitle');let proposed={id:uid(),token:uid()+uid()};try{busy=true;let d=await api('create-room',{id:proposed.id,adminKey:proposed.token,title},'');teacherSession={...proposed,...d.room};rememberRoom(teacherSession);write(RK,teacherSession);await fetchBoard();render();}catch(err){toast(err.message);}finally{busy=false;}}else if(e.target.id==='answerForm'||e.target.id==='finalForm'){let isFinal=e.target.id==='finalForm',data=Object.fromEntries(new FormData(e.target));await action(isFinal?'unlock':'submit',isFinal?{code:data.code}:{input:data});}});
let draftTimer;document.addEventListener('input',e=>{if(e.target.closest('.lab'))updateLab();if(e.target.closest('#answerForm')&&state?.status==='active'){let i=state.solved.length;state.drafts[i]??={};state.drafts[i][e.target.name]=e.target.value;save();clearTimeout(draftTimer);draftTimer=setTimeout(()=>syncDraft(i),900);}});
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'rules':rulesDialog();break;case 'shop':await shopDialog();break;case 'buy-skill':await buySkill(b.dataset.skill);break;case 'lab-pipe':rotatePipe(Number(b.dataset.cell));break;case 'check-pipe':checkPipe();break;case 'choose-level':if(busy)return;busy=true;try{let d=await api('choose-level',{id:session.id,level:Number(b.dataset.level)});apply(d);render();}catch(e){toast(e.message);}finally{busy=false;}break;case 'lab-truth':b.textContent=b.textContent==='?'?'Đ':b.textContent==='Đ'?'S':'?';break;case 'lab-token':b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')==='true'?'false':'true');break;case 'start':if(!busy)await start();break;case 'resume':await refresh(true);if(!state)break;screen=state.status==='waiting'?'waiting':state.status==='active'?'play':'result';render();break;case 'result':screen='result';render();break;case 'continue':feedback='';screen='play';render();window.scrollTo(0,0);break;case 'hints':hintDialog();break;case 'close-hints':dlg.close();break;case 'buy-hint':if(busy||performance.now()-hintTap<700)return;hintTap=performance.now();b.disabled=true;await action('hint',{});break;case 'download':download('bao-cao-'+state.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]+/g,'-')+'.json',G.report(state,now()));break;case 'print':window.print();break;case 'new':if(state?.status==='active'||state?.status==='waiting'){toast('Phiên này chưa kết thúc. Tiếp tục trên thiết bị đã vào phòng.');break;}state=null;session=null;screen='landing';localStorage.removeItem(KEY);localStorage.removeItem(DK);render();break;case 'begin-room':if(busy)return;try{busy=true;await api('begin',{id:teacherSession.id,revision:board?.room.revision},teacherSession.token);await fetchBoard();render();}catch(err){toast(err.message);}finally{busy=false;}break;case 'reset-room':case 'delete-room':case 'remove-team':managementDialog(b.dataset.action,b.dataset.team);break;case 'confirm-management':await confirmManagement();break;case 'cancel-management':managementDlg.close();managementPending=null;break;case 'select-room':await selectRoom(b.dataset.room);break;case 'create-another-room':if(busy)return;teacherSession=null;board=null;reports=[];localStorage.removeItem(RK);render();break;case 'csv':exportCSV();break;}});
function exportCSV(){const cell=v=>{let x=String(v);if(/^[=+\-@\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"';};let rows=[['Hạng','Nhóm','Điểm','Trạng thái','Khóa hoàn tất','Thực chơi (giây)','Phạt (giây)','Xếp hạng (giây)','Hint 1','Hint 2','Hint 3','Hint 4','Hint 5','Lượt sai'],...sorted().map((r,i)=>[i+1,r.team,r.score||0,r.status,r.completed,Math.floor(r.elapsedMs/1000),r.penaltyMs/1000,Math.floor(r.adjustedMs/1000),...r.hints,r.wrong])];download('bang-xep-hang-cuu-ho.csv','\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n'));}
async function syncDraft(i){if(!session||!state||state.status!=='active'||state.solved.length!==i)return;try{await api('draft',{id:session.id,lock:i,input:state.drafts[i]||{}});}catch{}}
function uid(){let b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;let h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}
function now(){return Date.now()-clockOffset;}
async function api(action,body={},token=session?.token){let response=await fetch('/api/escape',{method:'POST',headers:{'Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})},body:JSON.stringify({action,...body,round:body.round??state?.round??1,requestId:uid()})});let d=await response.json();if(!response.ok){let error=Object.assign(Error(d.error||'Chưa kết nối được máy chủ.'),{code:d.code,status:response.status});endStudentSession(error);throw error;}clockOffset=Date.now()-d.serverNow;return d;}
function apply(d){if(!d.state)return;let cache=read(DK,{}),round=d.state.round||1;let changedRound=state?.id===d.state.id&&(state.round||1)!==round;let drafts=state?.id===d.state.id&&!changedRound?state.drafts:cache.id===d.state.id&&(cache.round||1)===round?(cache.drafts||{}):{};if(!state||state.id!==d.state.id||d.state.revision>=state.revision){state={...d.state,drafts};if(changedRound){clearTimeout(draftTimer);feedback='';lastDigit=null;pipeTurns=Array(9).fill(0);sessionNotice='Giáo viên đã reset phòng. Điểm, hint và tiến độ đã về 0. Đội chờ lượt chơi mới.';if(dlg.open)dlg.close();save();}}if(d.serverNow)clockOffset=Date.now()-d.serverNow;}
function endStudentSession(error){if(!['ROOM_DELETED','TEAM_REMOVED'].includes(error.code)||screen==='teacher')return false;clearTimeout(draftTimer);sessionNotice=error.message;state=null;session=null;peers=[];feedback='';localStorage.removeItem(KEY);localStorage.removeItem(DK);if(dlg.open)dlg.close();screen='landing';render();return true;}
async function action(kind,data){if(busy||!session)return;busy=true;updateClock();try{let d=await api(kind,{id:session.id,...data,...(kind==='hint'?{level:state.hints[state.solved.length].length+1}:{})});apply(d);if(kind==='hint'){if(d.result.ok){hintDialog();toast(d.result.cost?'Đã ghi nhận gợi ý mức '+d.result.level+' · Cộng '+d.result.cost/60000+' phút':'Mức gợi ý này đã được ghi nhận. Không cộng phạt lần nữa.');root.querySelector('[data-action="hints"]').textContent='Gợi ý · '+state.hints[state.solved.length].length+'/3';}else{if(dlg.open)dlg.close();screen=state.status==='active'?'play':'result';render();}}else handleReply(d.result);}catch(e){if(endStudentSession(e))return;toast(e.message);let f=document.getElementById('feedback');if(f)f.textContent='Chưa nhận được xác nhận của máy chủ. Câu trả lời vẫn được giữ; đang đồng bộ lại tiến độ.';await refresh(true);}finally{busy=false;updateClock();}}
async function refresh(force=false){if(!session||busy&&!force)return;let requested=session;try{let old=state?.status,oldRound=state?.round||1,r=await fetch('/api/escape?kind=state&id='+encodeURIComponent(requested.id),{headers:{Authorization:'Bearer '+requested.token},cache:'no-store'}),d=await r.json();if(session?.id!==requested.id)return;if(!r.ok)throw Object.assign(Error(d.error),{code:d.code});apply(d);if(state.status==='waiting'){screen='waiting';if(old!=='waiting'||oldRound!==state.round||force)render();}else if((old==='waiting'||oldRound!==state.round)&&state.status==='active'){sessionNotice='';screen='play';render();}else if((state.status==='completed'||state.status==='timeout')&&(old!==state.status||screen!=='result')){screen='result';if(dlg.open)dlg.close();render();}if(dlg.open&&dlg.dataset.kind==='hint'&&state.status==='active')hintDialog();updateClock();}catch(e){if(session?.id!==requested.id)return;if(endStudentSession(e))return;if(force)toast(e.message||'Chưa kết nối được máy chủ.');}}
async function fetchBoard(){if(!teacherSession)return;let requested=teacherSession,r=await fetch('/api/escape?kind=board&id='+encodeURIComponent(requested.id),{headers:{Authorization:'Bearer '+requested.token},cache:'no-store'}),d=await r.json();if(teacherSession?.id!==requested.id)return;if(!r.ok){if(d.code==='ROOM_DELETED'){forgetRoom(requested.id);teacherSession=null;board=null;reports=[];localStorage.removeItem(RK);render();toast('Phòng này đã được xóa. Chọn phòng khác hoặc tạo phòng mới.');return;}throw Error(d.error);}board=d;reports=d.teams;teacherSession={...requested,...d.room};rememberRoom(teacherSession);write(RK,teacherSession);}
function waiting(){return `${header()}<main class="success"><div class="eyebrow">Đã vào phòng ${esc(state.room)}</div><h1>Đội đã sẵn sàng.</h1><p><strong>${esc(state.name)}</strong></p>${sessionNotice?`<p class="notice" role="status">${esc(sessionNotice)}</p>`:''}<p>Phân vai, chuẩn bị giấy nháp và bút. Khi giáo viên bắt đầu, hồ sơ đầu tiên và đồng hồ sẽ tự mở.</p><p class="small muted">Giữ trang này mở. Không cần nhập lại tên hoặc mã phòng.</p></main>`;}

function rememberRoom(room){let index=managedRooms.findIndex(r=>r.id===room.id);if(index<0)managedRooms.push({...room});else managedRooms[index]={...managedRooms[index],...room};write(ROOMS_KEY,managedRooms);}
function forgetRoom(id){managedRooms=managedRooms.filter(r=>r.id!==id);write(ROOMS_KEY,managedRooms);}
function roomPicker(){return managedRooms.length?`<section class="room-picker" aria-label="Các phòng đã tạo"><p class="small muted">Phòng đã lưu trên trình duyệt này</p><div class="room-list">${managedRooms.map(r=>`<button data-action="select-room" data-room="${esc(r.id)}" aria-pressed="${r.id===teacherSession?.id}"><strong>${esc(r.title||'Phòng cứu hộ')}</strong><span>${esc(r.code)} · ${r.started?'Đã bắt đầu':'Chờ bắt đầu'}</span></button>`).join('')}</div></section>`:'';}
async function selectRoom(id){if(busy||managementDlg.open)return;let room=managedRooms.find(r=>r.id===id);if(!room)return;busy=true;teacherSession=room;board=null;reports=[];write(RK,room);render();try{await fetchBoard();render();}catch(e){toast(e.message);}finally{busy=false;}}
const managementDlg=document.createElement('dialog');managementDlg.id='managementDialog';managementDlg.setAttribute('aria-labelledby','managementTitle');document.body.appendChild(managementDlg);
function managementDialog(kind,teamId){if(busy||!teacherSession||!board)return;let team=reports.find(r=>r.id===teamId);if(kind==='remove-team'&&!team)return;let room=board.room;managementPending={kind,teamId,room:{...teacherSession},revision:room.revision};let title=kind==='reset-room'?'Reset phòng để chơi lại':kind==='delete-room'?'Xóa phòng '+room.code:'Xóa đội '+team.team;let content=kind==='reset-room'?`<p>Phòng <strong>${esc(room.title)}</strong> · ${esc(room.code)} · ${reports.length} đội.</p><ul><li>Giữ nguyên mã phòng và tên các đội hiện có.</li><li>Xóa toàn bộ điểm, hint, phạt, bản nháp, kết quả và lịch sử kỹ năng của lượt này.</li><li>Các đội tự trở về màn hình chờ. Giáo viên bấm Bắt đầu để mở lượt 30 phút mới.</li></ul>`:kind==='delete-room'?`<p>Đóng phòng <strong>${esc(room.title)}</strong> · ${esc(room.code)} và xóa khỏi danh sách quản lý. ${reports.length} đội trong phòng sẽ được thông báo và rời lượt chơi.</p><p>Mã ${esc(room.code)} sẽ không vào chơi được nữa. Kết quả của phòng không còn hiển thị. Có thể tải CSV trước khi xóa.</p>`:`<p>Đội <strong>${esc(team.team)}</strong> sẽ bị loại khỏi danh sách và bảng xếp hạng của phòng ${esc(room.code)}. Thiết bị của đội sẽ nhận thông báo và trở về trang vào phòng.</p><p>Các đội khác tiếp tục chơi. Những điểm kỹ năng họ đã tiêu vẫn được giữ nguyên. Tên đội vừa xóa có thể dùng để vào lại.</p>`;managementDlg.innerHTML=`<h2 id="managementTitle">${esc(title)}</h2>${content}${kind==='remove-team'?'':`<p><button data-action="csv" ${reports.length?'':'disabled'}>Tải kết quả CSV trước khi tiếp tục</button></p>`}${kind==='delete-room'?`<label for="deleteRoomCode">Nhập mã ${esc(room.code)} để xác nhận</label><input id="deleteRoomCode" autocomplete="off" maxlength="6" placeholder="Mã phòng cần xóa">`:''}<p id="managementError" class="feedback" role="alert"></p><div class="flex"><button data-action="cancel-management">Hủy</button><button class="danger confirm-danger" data-action="confirm-management">${kind==='reset-room'?'Xác nhận reset':kind==='delete-room'?'Xác nhận xóa phòng':'Xác nhận xóa đội'}</button></div>`;managementDlg.showModal();}
async function confirmManagement(){if(busy||!managementPending)return;let operation=managementPending,button=managementDlg.querySelector('[data-action="confirm-management"]'),errorBox=document.getElementById('managementError');let confirmCode=operation.kind==='delete-room'?document.getElementById('deleteRoomCode').value.trim().toUpperCase():operation.room.code;if(operation.kind==='delete-room'&&confirmCode!==operation.room.code){errorBox.textContent='Mã xác nhận chưa khớp. Chưa xóa phòng.';return;}busy=true;button.disabled=true;try{await api(operation.kind,{id:operation.room.id,revision:operation.revision,teamId:operation.teamId,confirmCode},operation.room.token);managementDlg.close();managementPending=null;if(operation.kind==='delete-room'){forgetRoom(operation.room.id);if(teacherSession?.id===operation.room.id){teacherSession=null;board=null;reports=[];localStorage.removeItem(RK);}}else await fetchBoard();render();toast(operation.kind==='reset-room'?'Đã reset phòng. Các đội chờ giáo viên bắt đầu lượt mới.':operation.kind==='delete-room'?'Đã xóa phòng. Mã phòng đã ngừng hoạt động.':'Đã xóa đội khỏi phòng.');}catch(e){errorBox.textContent=e.message+(e.status===409?' Bấm Hủy rồi mở lại thao tác sau khi kiểm tra phòng.':'');await fetchBoard().catch(()=>{});}finally{busy=false;button.disabled=false;}}
if(teacherSession)rememberRoom(teacherSession);

async function boot(){if(new URLSearchParams(location.search).get('view')==='teacher'){screen='teacher';if(teacherSession){try{await fetchBoard();}catch(e){toast(e.message);}}render();}else if(session){await refresh(true);if(state)screen=state.status==='waiting'?'waiting':state.status==='active'?'play':'result';render();}else render();}
boot();setInterval(updateClock,500);setInterval(()=>{if(screen==='teacher'&&teacherSession&&!busy)fetchBoard().then(()=>{let focused=document.activeElement;if(!focused||focused.tagName!=='INPUT')render();}).catch(()=>{let n=document.getElementById('boardStatus');if(n)n.textContent='Mất kết nối. Đang thử cập nhật lại…';});else if(screen!=='teacher')refresh();},3000);
})();
